using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class AddReverseCorrectionWater {
 public static string Main(){Vector3[] points=null;float start=0,end=0;foreach(string scene in new[]{"DansBackyardReverse","DansBackyardForward"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");var root=GameObject.Find("Reverse optional forest shortcuts").transform;var b=root.GetComponentsInChildren<WoodlandRoute>().FirstOrDefault(b=>b.title.StartsWith("Storm"));bool temporary=!b;if(temporary){b=root.gameObject.AddComponent<WoodlandRoute>();b.points=points;}else{points=b.points.ToArray();start=b.undergroundStart;end=b.undergroundEnd;}
 for(float s=start+37;s<end-3;s+=2.5f){if((s-start-4)%24>18)continue;var p=b.At(s,out var f);var side=Vector3.Cross(Vector3.up,f).normalized;var g=new GameObject("Shallow drain ripple footprint");g.transform.SetParent(root);g.transform.SetPositionAndRotation(p+side*.3f,Quaternion.LookRotation(Vector3.ProjectOnPlane(f,Vector3.up)));g.transform.localScale=new(2.7f,.06f,2.5f);g.AddComponent<ShallowWater>();}
 if(temporary)Object.DestroyImmediate(b);EditorSceneManager.MarkSceneDirty(root.gameObject.scene);EditorSceneManager.SaveScene(root.gameObject.scene);}AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");File.WriteAllText("Docs/ReverseCorrection/water-feedback.txt","Existing ShallowWater/WaterFeedback reused in shallow level/decreasing-grade sections; no new water physics. Above-ground vehicles excluded by existing immersion-height test.");return "Existing shallow water ripple/splash feedback assigned locally";}
}
